import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Sheet from "../../ui/sheet";

const sheetTitleId = "sheet-basic-title";
const sheetDescriptionId = "sheet-basic-description";

// MODEL

export const Model = S.Struct({
  open: S.Boolean,
});
export type Model = typeof Model.Type;

// MESSAGE

export const OpenedSheet = m("OpenedSheet");
export const ClosedSheet = m("ClosedSheet");
export const Message = S.Union([OpenedSheet, ClosedSheet]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ open: false }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      OpenedSheet: () => [evo(model, { open: () => true }), []],
      ClosedSheet: () => [evo(model, { open: () => false }), []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return Sheet.rootView<Message>({
    children: [
      Sheet.triggerView<Message>({
        onOpen: OpenedSheet(),
        children: [h.span([], ["Open"])],
      }),
      Sheet.portalView<Message>({
        open: model.open,
        children: [
          Sheet.overlayView<Message>({}),
          Sheet.contentView<Message>({
            ariaDescribedBy: sheetDescriptionId,
            ariaLabelledBy: sheetTitleId,
            children: [
              Sheet.headerView<Message>({
                children: [
                  Sheet.titleView<Message>({
                    id: sheetTitleId,
                    label: "Edit profile",
                  }),
                  Sheet.descriptionView<Message>({
                    id: sheetDescriptionId,
                    label:
                      "Make changes to your profile here. Click save when you're done.",
                  }),
                ],
              }),
              h.div(
                [h.Class("grid gap-4 py-4")],
                [
                  h.label(
                    [h.For("sheet-name"), h.Class("text-sm font-medium")],
                    ["Name"]
                  ),
                  h.input([
                    h.Id("sheet-name"),
                    h.Value("Pedro Duarte"),
                    h.Class(
                      "h-10 rounded-md border border-gray-300 px-3 text-sm"
                    ),
                  ]),
                  h.label(
                    [h.For("sheet-username"), h.Class("text-sm font-medium")],
                    ["Username"]
                  ),
                  h.input([
                    h.Id("sheet-username"),
                    h.Value("@peduarte"),
                    h.Class(
                      "h-10 rounded-md border border-gray-300 px-3 text-sm"
                    ),
                  ]),
                ]
              ),
              Sheet.footerView<Message>({
                children: [
                  h.button(
                    [
                      h.Type("button"),
                      h.OnClick(ClosedSheet()),
                      h.Class(
                        "rounded-md bg-gray-950 px-4 py-2 text-sm font-medium text-white"
                      ),
                    ],
                    ["Save changes"]
                  ),
                ],
              }),
              Sheet.closeView<Message>({
                onClose: ClosedSheet(),
                children: [h.span([], ["x"])],
              }),
            ],
          }),
        ],
      }),
    ],
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as SheetBasicExample from "./main";

describe("Sheet Basic example", () => {
  test("opens and closes the sheet", () => {
    Scene.scene(
      {
        update: SheetBasicExample.update,
        view: SheetBasicExample.view,
      },
      Scene.with(SheetBasicExample.init()[0]),
      Scene.expect(Scene.role("dialog")).toBeAbsent(),
      Scene.click(Scene.role("button", { name: "Open" })),
      Scene.expect(Scene.role("dialog")).toExist(),
      Scene.expect(Scene.text("Edit profile")).toExist(),
      Scene.click(Scene.role("button", { name: "Save changes" })),
      Scene.expect(Scene.role("dialog")).toBeAbsent()
    );
  });
});
